// return true if we've joined 2 groups, false if they're in the same group.
function union(v1, v2, groups) {
    function findRoot(g) {
        while (groups[g] !== g) {
            g = groups[g];
        }

        return g;
    }

    if (groups[v1] < 0 && groups[v2] < 0) {
        groups[v1] = v1;
        groups[v2] = v1;

        return true;
    }

    if (groups[v1] >= 0 && groups[v2] >= 0) {
        let g1 = findRoot(groups[v1]);
        let g2 = findRoot(groups[v2]);

        groups[g1] = g2;

        return g1 !== g2;
    }

    if (groups[v2] >= 0) {
        groups[v1] = v2;
    } else {
        groups[v2] = v1;
    }

    return true;
}
